<template>
  <div class="publish-container">
    <NavBar />
    
    <div class="content-wrapper">
      <el-card class="publish-card">
        <template #header>
          <div class="card-header">
            <span>发布商品</span>
          </div>
        </template>
        
        <el-form 
          ref="publishFormRef"
          :model="form"
          :rules="rules"
          label-width="100px"
          class="publish-form"
        >
          <el-form-item label="商品标题" prop="title">
            <el-input v-model="form.title" placeholder="请输入商品标题（如：99新 iPad Air 5）" />
          </el-form-item>
          
          <el-form-item label="商品价格" prop="price">
            <el-input-number v-model="form.price" :precision="2" :step="1" :min="0" />
            <span class="unit">元</span>
          </el-form-item>
          
          <el-form-item label="商品分类" prop="category">
            <el-select v-model="form.category" placeholder="请选择分类">
              <el-option label="书籍教材" value="书籍教材" />
              <el-option label="电子数码" value="电子数码" />
              <el-option label="生活用品" value="生活用品" />
              <el-option label="美妆护肤" value="美妆护肤" />
              <el-option label="运动器材" value="运动器材" />
              <el-option label="其他" value="其他" />
            </el-select>
          </el-form-item>
          
          <el-form-item label="商品描述" prop="description">
            <el-input 
              v-model="form.description" 
              type="textarea" 
              :rows="4" 
              placeholder="描述一下商品的成色、入手渠道、转手原因等..." 
            />
          </el-form-item>
          
          <el-form-item label="商品图片">
            <el-upload
              class="avatar-uploader"
              action="#"
              :show-file-list="false"
              :auto-upload="false"
              :on-change="handleFileChange"
            >
              <img v-if="imageUrl" :src="imageUrl" class="avatar" />
              <el-icon v-else class="avatar-uploader-icon"><Plus /></el-icon>
            </el-upload>
            <div class="upload-tip">支持 jpg/png 格式，大小不超过 2MB</div>
          </el-form-item>
          
          <el-form-item>
            <el-button type="primary" @click="submitForm" :loading="loading">立即发布</el-button>
            <el-button @click="$router.back()">取消</el-button>
          </el-form-item>
        </el-form>
      </el-card>
    </div>
  </div>
</template>

<script setup>
import { ref, reactive } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { Plus } from '@element-plus/icons-vue'
import NavBar from '@/components/NavBar.vue'
// import { publishProduct, uploadProductImage } from '@/api/product' // 暂时注释，等待后端接口

const router = useRouter()
const publishFormRef = ref(null)
const loading = ref(false)
const imageUrl = ref('')
const imageFile = ref(null)

const form = reactive({
  title: '',
  price: 0,
  category: '',
  description: ''
})

const rules = {
  title: [{ required: true, message: '请输入商品标题', trigger: 'blur' }],
  price: [{ required: true, message: '请输入价格', trigger: 'blur' }],
  category: [{ required: true, message: '请选择分类', trigger: 'change' }],
  description: [{ required: true, message: '请输入商品描述', trigger: 'blur' }]
}

const handleFileChange = (file) => {
  imageFile.value = file.raw
  imageUrl.value = URL.createObjectURL(file.raw)
}

const submitForm = async () => {
  if (!publishFormRef.value) return
  
  await publishFormRef.value.validate(async (valid) => {
    if (valid) {
      loading.value = true
      try {
        // TODO: 先上传图片获取URL，再提交表单
        // const formData = new FormData()
        // formData.append('file', imageFile.value)
        // const imgRes = await uploadProductImage(formData)
        
        // const productData = { ...form, image: imgRes.data.url }
        // await publishProduct(productData)
        
        // 模拟成功
        await new Promise(resolve => setTimeout(resolve, 1000))
        
        ElMessage.success('发布成功')
        router.push('/')
      } catch (error) {
        console.error(error)
        ElMessage.error('发布失败')
      } finally {
        loading.value = false
      }
    }
  })
}
</script>

<style scoped>
.publish-container {
  min-height: 100vh;
  background-color: #f5f7fa;
}

.content-wrapper {
  max-width: 800px;
  margin: 20px auto;
  padding: 0 20px;
}

.publish-card {
  border-radius: 8px;
}

.card-header {
  font-size: 18px;
  font-weight: bold;
}

.unit {
  margin-left: 10px;
  color: #606266;
}

.avatar-uploader .el-upload {
  border: 1px dashed #d9d9d9;
  border-radius: 6px;
  cursor: pointer;
  position: relative;
  overflow: hidden;
  transition: var(--el-transition-duration-fast);
}

.avatar-uploader .el-upload:hover {
  border-color: var(--el-color-primary);
}

.avatar-uploader-icon {
  font-size: 28px;
  color: #8c939d;
  width: 148px;
  height: 148px;
  text-align: center;
  line-height: 148px;
  border: 1px dashed #d9d9d9;
  border-radius: 6px;
}

.avatar {
  width: 148px;
  height: 148px;
  display: block;
}

.upload-tip {
  font-size: 12px;
  color: #909399;
  margin-top: 5px;
}
</style>